"Das Bild konnte nicht gelesen werden.":"Imej tidak dapat dibaca.",
"Das Bild liegt als Vorlage auf der Ebene. Größe, Lage, Drehung und Deckkraft danach im Eigenschaftenfenster einstellen (z. B. Breite nach einer bekannten Abmessung).":"Imej terletak pada satah sebagai templat. Kemudian tetapkan saiz, kedudukan, putaran dan kelegapan dalam panel sifat (cth. lebar mengikut ukuran yang diketahui).",
"Das Ergebnis des Geometriekerns ist unlesbar":"Hasil teras geometri tidak boleh dibaca",
"Das Ergebnis konnte nicht geschrieben werden":"Hasil tidak dapat ditulis",
"Das Maß muss größer als 0 sein.":"Dimensi mesti lebih besar daripada 0.",
"Das Netz bleibt ein Dreiecksnetz (kein B-Rep). Bearbeiten unter NETZ: Reparieren, Reduzieren, Glätten, Ebenenschnitt … 3D-Frässtrategien in der Fertigung können es direkt bearbeiten.":"Jejaring kekal sebagai jejaring segi tiga (bukan B-Rep). Edit di bawah JEJARING: Baiki, Kurangkan, Licinkan, Keratan satah … Strategi pengisaran 3D dalam Pembuatan boleh memesinnya secara terus.",
"Das Profil darf die Achse nicht schneiden. Eine offene Linie in der Skizze kann als Achse dienen.":"Profil tidak boleh memotong paksi. Garis terbuka dalam lakaran boleh berfungsi sebagai paksi.",
"Das Profil mit den jetzigen Werten überschreiben":"Tulis ganti profil dengan nilai semasa",
"Das Profil wird entlang einer Linie/eines Linienzugs geführt. Profil am besten senkrecht zum Pfadanfang zeichnen (z. B. Profil auf XZ, Pfad auf XY).":"Profil disapu sepanjang garisan/polibaris. Sebaik-baiknya lukis profil serenjang dengan permulaan laluan (cth. profil pada XZ, laluan pada XY).",
"Das Profil wird von der Skizzenebene aus erhaben oder vertieft geprägt.":"Profil ditimbul atau ditenggelamkan bermula dari satah lakaran.",
"Das Rohteil ist der Quader um den gewählten Körper (plus Versatz).":"Bahan mentah ialah kuboid di sekeliling jasad yang dipilih (campur ofset).",
"Das Setup hat keine Operationen.":"Setup tidak mempunyai operasi.",
"Das Werkzeug fräst in Kreisen, deren Mitte entlang der Nut wandert. Es ist nie über die volle Breite im Eingriff – das erlaubt große Zustelltiefen und schont Fräser und Spindel. Der Fräser sollte etwa 60 % der Nutbreite haben.":"Alat mengisar dalam bulatan yang pusatnya bergerak sepanjang alur. Ia tidak pernah terlibat pada lebar penuh – ini membolehkan kedalaman pemotongan besar dan lebih lembut untuk pengisar dan gelendong. Pengisar hendaklah kira-kira 60 % daripada lebar alur.",
"Das Werkzeug schneidet die Fläche nicht":"Alat tidak bersilang dengan permukaan",
"Das Werkzeug schneidet in Richtung der ausgewählten Flächen, bis es die angegebenen Aufmaße erreicht.":"Alat memotong ke arah muka yang dipilih sehingga mencapai elaun yang ditetapkan.",
"Das Werkzeug taucht wie ein Bohrer senkrecht ein, Reihe für Reihe, bis auf das Modell plus Aufmaß. Die Schnittkraft wirkt entlang der Spindel: geeignet für lange Werkzeuge, tiefe Kavitäten und wenig steife Maschinen. Das Werkzeug muss über die Mitte schneiden.{0}":"Alat menusuk menegak seperti gerudi, baris demi baris, sehingga model ditambah elaun. Daya pemotongan bertindak sepanjang gelendong: sesuai untuk alat panjang, rongga dalam dan mesin yang kurang tegar. Alat mesti memotong melepasi pusat.{0}",
"Das Werkzeug vermeidet diese Flächen unter Berücksichtigung der angegebenen Sicherheitsabstände (Spanner, Schraubstock).":"Alat mengelakkan muka ini dengan mengambil kira kelegaan yang ditetapkan (pengapit, ragum).",
"Das Werkzeug vermeidet diese Flächen, während es in der Nähe liegende Flächen bearbeitet, und hält die Sicherheitsabstände ein.":"Alat mengelakkan muka ini semasa memesin muka berdekatan dan mematuhi kelegaan.",
"Das erste Esc bricht nur das Werkzeug oder die Auswahl ab – ein Esc zu viel schließt die Skizze nicht":"Esc pertama hanya membatalkan alat atau pilihan – satu Esc berlebihan tidak menutup lakaran",
"Das ist keine Bohrung (Verrundung oder Zapfen) – bitte die Innenwand einer Bohrung anklicken.":"Ini bukan lubang (fillet atau pin) – sila klik dinding dalam lubang.",
"Das ist keine Bohrung (Zylinderfläche) – bitte die Bohrungswand anklicken.":"Ini bukan lubang (permukaan silinder) – sila klik dinding lubang.",
"Das ist keine WerkFab-Design-Datei.":"Ini bukan fail reka bentuk WerkFab.",
"Das ist keine schräge Kante – beide Enden der Fasenkante anklicken.":"Ini bukan tepi condong – klik kedua-dua hujung tepi chamfer.",
"Datei":"Fail",
"Datei ist keine WerkFab-Einstellungsdatei.":"Fail ini bukan fail tetapan WerkFab.",
"Datei konnte nicht geöffnet werden:":"Fail tidak dapat dibuka:",
