"Dieser Browser unterstützt keine SpaceMouse (WebHID). Bitte Chrome, Edge oder die Desktop-App verwenden.":"Pelayar ini tidak menyokong SpaceMouse (WebHID). Sila gunakan Chrome, Edge atau aplikasi desktop.",
