"Eigene Maße und Hinweise lassen sich im Blatt mit der Maus ziehen (Abstand der Maßlinie, Winkel der Hinweislinie, Radius des Winkelbogens). Zwei Ecken anklicken = Längenmaß. Einen Kreisrand in der Draufsicht anklicken = Durchmesser (bzw. Radius). Winkel: erst die Ecke, dann je einen Eckpunkt auf beiden Schenkeln. Fase: beide Enden der schrägen Kante – ergibt z. B. 2×45°. Im Textfeld hinter jedem Maß steht ein Zusatz wie ±0,1, H7 oder 4×.":"Dimensi dan nota sendiri boleh diseret pada lembaran dengan tetikus (jarak garis dimensi, sudut garis penunjuk, jejari arka sudut). Klik dua sudut = dimensi panjang. Klik tepi bulatan dalam pandangan atas = diameter (atau jejari). Sudut: bucu dahulu, kemudian satu titik sudut pada kedua-dua kaki. Chamfer: kedua-dua hujung tepi condong – menghasilkan cth. 2×45°. Dalam medan teks selepas setiap dimensi terdapat tambahan seperti ±0,1, H7 atau 4×.",
