"Ein runder Fräser lässt in jeder Innenecke seinen Radius stehen – ein eckiges Gegenstück passt dann nicht hinein. Der Freistich fährt an jeder scharfen Innenecke kurz in die Ecke und zurück.{0}{1}":"Pengisar bulat meninggalkan jejarinya pada setiap sudut dalam – pasangan bersudut tidak akan muat. Pelepasan bergerak sebentar ke dalam sudut dan kembali pada setiap sudut dalam yang tajam.{0}{1}",
