"Erhebung braucht zwei Skizzen mit geschlossenen Profilen auf verschiedenen Ebenen.":"Loft memerlukan dua lakaran dengan profil tertutup pada satah yang berlainan.",
"Erhebung braucht zwei Skizzen mit je einer Kurve (auf verschiedenen Ebenen).":"Loft memerlukan dua lakaran dengan satu lengkung setiap satu (pada satah yang berlainan).",
"Erhebung nicht möglich – Querschnitte prüfen (je ein geschlossenes Profil, nicht verdreht)":"Loft tidak dapat dibuat – semak keratan rentas (masing-masing satu profil tertutup, tidak terpiuh)",
