"Erst die Fläche an dem Körper anklicken, der bewegt wird, dann die Zielfläche am anderen Körper. Der Körper wird gedreht und verschoben, bis der erste Klickpunkt auf dem zweiten liegt und die Flächen aufeinander liegen.":"Klik dahulu muka pada jasad yang digerakkan, kemudian muka sasaran pada jasad lain. Jasad diputar dan digerakkan sehingga titik klik pertama terletak pada yang kedua dan muka bertindih.",
"Erst die Kante an dem Körper anklicken, der bewegt wird, dann die Zielkante am anderen Körper. Gerade Kanten kommen deckungsgleich aufeinander (Mitte auf Mitte); bei Kreiskanten – Bohrung und Zapfen – werden die Achsen gleich gerichtet und die Mittelpunkte zusammengelegt.":"Klik dahulu tepi pada jasad yang digerakkan, kemudian tepi sasaran pada jasad lain. Tepi lurus dibuat bertindih (tengah ke tengah); untuk tepi bulat – lubang dan pin – paksi dijajarkan dan titik pusat disatukan.",
