"Erst eine Skizze oder Konstruktionsebene wählen – dann schaut Strg+8 senkrecht darauf.":"Pilih lakaran atau satah binaan dahulu – kemudian Ctrl+8 memandang tegak lurus padanya.",
"Erst einen Körper in KONSTRUKTION erstellen oder ein Netz (STL) einfügen.":"Buat jasad dalam REKA BENTUK dahulu atau sisipkan jejaring (STL).",
