"Flächen am Körper":"Muka pada jasad",
"Flächen am Teilende (Zweiflach, Vierkant, Sechskant) mit einem angetriebenen Schaftfräser entlang Z. Schlüsselweite = doppelter Abstand der Fläche von der Drehachse. X und C fahren gemeinsam (Polar-Interpolation, Fanuc G12.1); ohne diese Vorlage im Postprozessor werden kurze X/C-Schritte ausgegeben.":"Permukaan rata pada hujung bahagian (dua rata, segi empat sama, heksagon) dengan pengisar hujung rata hidup sepanjang Z. Lebar merentas rata = dua kali jarak permukaan rata dari paksi putaran. X dan C bergerak bersama (interpolasi kutub, Fanuc G12.1); tanpa templat ini dalam pasca-pemproses, langkah X/C pendek dikeluarkan.",
"Flächen anklicken, die aufgedickt werden (erneut klicken entfernt).":"Klik muka yang akan ditebalkan (klik semula untuk membuang).",
