"Jede Achse einzeln: Kante, Ecke, Fläche oder Bohrung anklicken. Nicht gesetzte Achsen kommen vom Rohteilpunkt.":"Setiap paksi secara berasingan: klik tepi, bucu, muka atau lubang. Paksi yang tidak ditetapkan diambil daripada titik bahan mentah.",
