"Jeder Kreis der Skizze wird um die Mitte (in Skizzenkoordinaten) gedreht wiederholt – ein Kreis im Abstand des Teilkreisradius ergibt einen Lochkreis.":"Setiap bulatan lakaran diulang dengan diputar mengelilingi pusat (dalam koordinat lakaran) – bulatan pada jarak jejari bulatan pic menghasilkan bulatan lubang.",
