"Kontur mit {0} Punkten – Okuma: G85 (LAP) mit Kontur G81…G80, Fanuc: G71 P…Q…. Die Steuerung schruppt mit ihrer eigenen Aufteilung; die Simulation hier ist die WerkFab-Bahn.":"Kontur dengan {0} titik – Okuma: G85 (LAP) dengan kontur G81…G80, Fanuc: G71 P…Q…. Kawalan memesin kasar dengan pembahagian sendiri; simulasi di sini ialah laluan WerkFab.",
