"Konturen außen und innen":"Kontur luar dan dalam",
"Konturen folgen dem Rand der dunklen Flächen. Die Mittellinie läuft in der Mitte der Striche – passend für Gravuren und Strichzeichnungen. „Geraden, Bögen und Kreise“ erkennt gerade Kanten, scharfe Ecken, Rundungen und Kreise; „Linienzüge“ folgt dem Bild Punkt für Punkt. Den Maßstab danach bei Bedarf mit „Vorlage kalibrieren“ oder „Skalieren“ anpassen.":"Kontur mengikut tepi kawasan gelap. Garis tengah berjalan di tengah goresan – sesuai untuk ukiran dan lukisan garisan. „Garis lurus, lengkok dan bulatan“ mengesan tepi lurus, sudut tajam, lengkung dan bulatan; „Polibaris“ mengikut imej titik demi titik. Selepas itu laraskan skala jika perlu dengan „Tentukur templat“ atau „Skala“.",
"Konturen mit Radiuskorrektur an der Steuerung (RL/RR) fahren mit APPR/DEP an und ab; die Steuerung berechnet Hilfspunkt und Korrektur selbst":"Kontur dengan pampasan jejari pada kawalan (RL/RR) didekati dan ditinggalkan dengan APPR/DEP; kawalan mengira titik bantu dan pampasan sendiri",
