"Kurven einer Skizze auf der Planfläche (quer zur Drehachse) mit einem angetriebenen Fräser entlang Z (X und C fahren gemeinsam; Fanuc: Polar-Interpolation G12.1). Offene Kurven werden hin und zurück gefräst. Tiefe ab Planfläche.":"Lengkung lakaran pada muka hujung (melintang paksi putaran) dengan pengisar hidup sepanjang Z (X dan C bergerak bersama; Fanuc: interpolasi kutub G12.1). Lengkung terbuka diisar pergi dan balik. Kedalaman dari muka hujung.",
"Kurven einer Skizze, die längs zur Drehachse liegt, werden auf den Umfang gewickelt und mit einem angetriebenen Fräser gefräst, der zur Achse zeigt (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Die Skizzenebene bestimmt den Winkel, an dem die Kontur sitzt; waagerechte Strecken in der Skizze werden Bögen um das Teil. Tiefe ab Außendurchmesser.":"Lengkung lakaran yang terletak sepanjang paksi putaran dililit pada lilitan dan diisar dengan pengisar hidup yang menghala ke paksi (Z dan C bergerak bersama; Fanuc: interpolasi silinder G7.1). Satah lakaran menentukan sudut kedudukan kontur; garis mendatar dalam lakaran menjadi lengkok mengelilingi bahagian. Kedalaman dari diameter luar.",
"Kurzbefehl":"Pintasan",
"Kurze Wege (bis zum Halteabstand) fährt das Werkzeug unten im Übergangsvorschub statt über die Rückzugshöhe – ohne Kollisionsprüfung, daher klein halten.":"Gerakan pendek (sehingga jarak kekal-bawah) dibuat di bawah dengan kadar suapan peralihan dan bukan melalui ketinggian tarik balik – tanpa semakan perlanggaran, jadi kekalkan nilai kecil.",
