"Mehrere aneinanderhängende Kanten zählen als eine Strecke: Der Radius läuft vom Anfang der Kette bis zu ihrem Ende, Stützpunkte gelten in % der ganzen Kettenlänge. Das rechnet der große Geometriekern.":"Beberapa tepi yang bersambung dikira sebagai satu laluan: jejari berjalan dari permulaan rantai hingga penghujungnya, titik kawalan diberikan dalam % panjang seluruh rantai. Ini dikira oleh kernel geometri penuh.",
