"Mit Stützpunkten läuft der Radius durch die angegebenen Werte (Lage in % der Kantenlänge). Das rechnet der große Geometriekern; beim ersten Mal lädt er einige Sekunden.":"Dengan titik kawalan, jejari melalui nilai yang diberikan (kedudukan dalam % panjang tepi). Ini dikira oleh kernel geometri penuh; kali pertama ia mengambil masa beberapa saat untuk dimuatkan.",
"Mit dem 3D-Taster kann nicht zerspant werden":"Prob 3D tidak boleh digunakan untuk memotong",
"Mit dem Fertigteil vergleichen: grün = auf Maß, blau = Restmaterial, rot = zu tief":"Bandingkan dengan bahagian siap: hijau = tepat saiz, biru = bahan berbaki, merah = terlalu dalam",
"Mit der Maus neben eine Kontur fahren (die Seite bestimmt die Richtung) · Esc beendet":"Gerakkan tetikus di sebelah kontur (sisi menentukan arah) · Esc menamatkan",
"Mit diesem Werkzeug kann nicht gefräst werden":"Alat ini tidak boleh digunakan untuk mengisar",
"Mit einem Gewindebohrer nur Zyklus „Gewindebohren“ – ein Bohrzyklus würde ihn abbrechen":"Dengan tap, gunakan hanya kitaran “Penarapan” – kitaran penggerudian akan mematahkannya",
"Mit mehreren Zustellungen wird die Gewindetiefe in Schritten gefräst, die jeweils etwa gleich viel abnehmen – schont kleine Gewindefräser und harte Werkstoffe. Der Leerdurchgang fährt die letzte Bahn noch einmal ohne Zustellung.":"Dengan beberapa laluan, kedalaman ulir diisar dalam langkah yang masing-masing membuang jumlah yang lebih kurang sama – lebih lembut untuk pengisar ulir kecil dan bahan keras. Laluan spring menjalankan laluan terakhir sekali lagi tanpa suapan.",
"Mit „Bohrzyklen“ im NC-Programm werden Steuerungszyklen ausgegeben (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85), sonst ausgeschriebene Bewegungen.":"Dengan “Kitaran penggerudian” dalam atur cara NC, kitaran kawalan dikeluarkan (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85); jika tidak, pergerakan dituliskan sepenuhnya.",
