"Nur Rechteck- und Kreistaschen gehen als Steuerungszyklus":"Hanya poket segi empat tepat dan bulat boleh dijadikan kitaran kawalan",
"Nur das bearbeiten, was ein größerer Fräser in Ecken stehen gelassen hat.":"Mesin hanya bahan yang ditinggalkan oleh pemotong lebih besar di bucu.",
"Nur die Stellen der Kontur nachfahren, die ein größerer Fräser nicht erreicht hat (Innenecken, enge Stellen). Ohne An-/Abfahrbögen, Haltestege und Schlichtdurchgänge; Korrektur im Rechner.":"Ikut semula hanya bahagian kontur yang tidak dapat dicapai oleh pemotong lebih besar (bucu dalam, tempat sempit). Tanpa lengkok masuk/keluar, tab dan laluan penamat; pampasan dalam komputer.",
"Nur dort, wo das Referenzwerkzeug nicht hinkam: flache Bereiche parallel, steile Bereiche als Wasserlinie. Mit einem Werkzeug aus der Liste zählt dessen Form mit – zum Beispiel was ein Torusfräser in den Hohlkehlen stehen lässt.":"Hanya di tempat alat rujukan tidak sampai: kawasan rata secara selari, kawasan curam sebagai garis air. Dengan alat daripada senarai, bentuknya turut diambil kira – contohnya apa yang ditinggalkan pengisar hidung bulat dalam fillet.",
"Nur ebene Flächen können als Skizzenebene dienen.":"Hanya muka rata boleh digunakan sebagai satah lakaran.",
"Nur ebene Flächen können extrudiert werden":"Hanya muka satah boleh diekstrusi",
"Nur ebene Flächen lassen sich ersetzen":"Hanya muka satah boleh diganti",
"Nur ebene Flächen und Zylinderflächen (Bohrungen, Zapfen) lassen sich versetzen":"Hanya muka satah dan muka silinder (lubang, cuk) boleh di-offset",
"Nur ebene Flächen, die nach oben zum Werkzeug zeigen (waagerecht in diesem Setup).":"Hanya muka rata yang menghadap ke atas ke arah alat (mengufuk dalam setup ini).",
