"Nut liegt nicht am Teil":"Alur tidak berada pada bahagian",
"Nut längs der Drehachse (z. B. Passfedernut) mit einem angetriebenen Fräser, der zur Achse zeigt; die Hauptspindel hält das Teil als C-Achse. Nutbreite = Fräser-Ø. Start/Ende Z in Modell-Z; reicht die Nut bis zur Planfläche, fährt der Fräser von vorn ein, sonst taucht er am Start ein. Tiefe ab Außendurchmesser.":"Alur sepanjang paksi putaran (cth. alur pasak) dengan pengisar hidup yang menghala ke paksi; gelendong utama memegang bahagian sebagai paksi C. Lebar alur = Ø pengisar. Z mula/hujung dalam Z model; jika alur sampai ke muka hujung, pengisar masuk dari hadapan, jika tidak ia menusuk pada permulaan. Kedalaman dari diameter luar.",
