"Offene Kanten werden rot angezeigt. „Reparieren“ schließt Löcher.":"Tepi terbuka ditunjukkan dalam warna merah. “Baiki” menutup lubang.",
"Offene Linie in einer Skizze wählen":"Pilih garis terbuka dalam lakaran",
"Offene oder geschlossene Kurven werden senkrecht zur Skizze gezogen – es entsteht eine Fläche (Wand ohne Dicke). Mit „Aufdicken“ oder „Zusammenfügen“ wird daraus ein Volumen.":"Lengkung terbuka atau tertutup diekstrusi serenjang dengan lakaran – hasilnya ialah permukaan (dinding tanpa ketebalan). Dengan „Tebalkan“ atau „Jahit“ ia menjadi pepejal.",
"Offene oder geschlossene Kurven werden um die Achse gedreht – es entsteht eine Fläche, kein Volumen.":"Lengkung terbuka atau tertutup diputar mengelilingi paksi – hasilnya ialah permukaan, bukan pepejal.",
"Ohne eigene Taste gilt der Standard „{0}“.":"Tanpa kekunci tersendiri, lalai “{0}” digunakan.",
"Ohne „Modelliert“ wird das Gewinde nur dargestellt (schnell). Modelliert wird die Gewindeform wirklich ausgeschnitten, z. B. für 3D-Druck. Bohrung für M8 = Ø6,8.":"Tanpa „Dimodelkan“ ulir hanya dipaparkan (pantas). Jika dimodelkan, bentuk ulir benar-benar dipotong, cth. untuk percetakan 3D. Lubang untuk M8 = Ø6,8.",
