"Okuma OSP: G28/G53 fahren dort nicht auf Maschinenkoordinaten (G53 hebt die Werkzeuglängenkorrektur auf) – Rückzug auf Sicherheitshöhe, keine XY-Referenzfahrt ausgegeben":"Okuma OSP: G28/G53 tidak bergerak ke koordinat mesin di sana (G53 membatalkan pembetulan panjang alat) – tarik balik ke ketinggian selamat, tiada gerakan rujukan XY dikeluarkan",
"Okuma OSP: keine Glättungsfunktion ausgegeben (G5.1 ist Fanuc) – Hi-Cut/Super-NURBS an der Maschine einstellen":"Okuma OSP: tiada fungsi pelicinan dikeluarkan (G5.1 ialah Fanuc) – tetapkan Hi-Cut/Super-NURBS pada mesin",
