"Wickelt die Skizzenkurven auf den Zylinder: X bleibt X, der Abstand quer zur Achse wird zum Bogen auf dem Abwicklungs-Ø (Drehung A). Die Skizze muss parallel zur A-Achse liegen, z. B. auf einer Tangentialebene. Gefräst wird in fester Tiefe unter der Teiloberfläche – für Gravuren, Schriften und Nuten rund um das Teil.":"Melilit lengkung lakaran pada silinder: X kekal X, jarak melintang paksi menjadi lengkok pada Ø lilitan (putaran A). Lakaran mesti selari dengan paksi A, cth. pada satah tangen. Pengisaran pada kedalaman tetap di bawah permukaan bahagian – untuk ukiran, tulisan dan alur mengelilingi bahagian.",
"Wie 3D-Kontur, aber das Werkzeug fährt ohne Absätze kontinuierlich nach unten – keine Eintauchmarken an steilen Wänden.":"Seperti kontur 3D, tetapi alat bergerak ke bawah secara berterusan tanpa anak tangga – tiada kesan tusukan pada dinding curam.",
