"Wie im System":"Seperti dalam sistem",
"Wie lange die Schneide schneiden darf, bevor sie getauscht wird. Das Fenster „Bearbeitungszeit“ rechnet daraus, wie viele Teile noch möglich sind.":"Berapa lama mata pemotong boleh memotong sebelum diganti. Tetingkap “Masa pemesinan” mengira daripadanya berapa banyak bahagian lagi yang boleh dibuat.",
